mapper.select:
select WO_ID,WO_NO,FROM_DATE,TO_DATE,FLINENO,WO_QTY,BOM_ID,ROWNUM RN from (
    select IERP_WO_MASTER.WO_ID,IERP_WO_MASTER.WO_NO,IERP_WO_MASTER.FROM_DATE,IERP_WO_MASTER.TO_DATE,T_WORKLINE.FLINENO,IERP_WO_MASTER.WO_QTY,IERP_WO_MASTER.BOM_ID,ROWNUM RN
    from IERP_WO_MASTER left join T_WORKLINE on IERP_WO_MASTER.WO_NO = T_WORKLINE.FWORKNO where IERP_WO_MASTER.STATUS in ('O') and ROWNUM <= (#{pageNum} * #{pageSize})
) v where RN > ((#{pageNum} - 1) * #{pageSize})
